"@vanssa/sylius-slider-plugin": {
  "slider": {
    "enabled": true,
    "fetch": "eager",
    "autoimport": {
      "@vanssa/sylius-slider-plugin/shop/styles/slider.scss": true
    }
  },
  "slide-video": {
    "enabled": true,
    "fetch": "eager"
  },
  "slider-settings": {
    "enabled": true,
    "fetch": "lazy"
  },
  "slider-slides-preview": {
    "enabled": true,
    "fetch": "lazy"
  },
  "rgba-color-picker": {
    "enabled": true,
    "fetch": "lazy",
    "autoimport": {
      "@simonwep/pickr/dist/themes/classic.min.css": true
    }
  },
  "responsive-copy": {
    "enabled": true,
    "fetch": "lazy"
  },
  "preview-frame": {
    "enabled": true,
    "fetch": "lazy"
  },
  "preset-applier": {
    "enabled": true,
    "fetch": "lazy"
  },
  "preset-gallery": {
    "enabled": true,
    "fetch": "lazy"
  },
  "form-context": {
    "enabled": true,
    "fetch": "lazy"
  },
  "animation-settings": {
    "enabled": true,
    "fetch": "lazy"
  },
  "image-upload-preview": {
    "enabled": true,
    "fetch": "lazy"
  },
  "mockup-picker": {
    "enabled": true,
    "fetch": "lazy"
  },
  "modal-portal": {
    "enabled": true,
    "fetch": "lazy"
  }
},
